        s = s.replace(/\\n?\`\`\`(?:([\\w+-]{1,20})\\n)?([\\s\\S]*?)\`\`\`\\n?/g, function (_, lang, code) { return hold("<pre><code>" + esc(code.replace(/^\\n|\\n$/g, "")) + "</code></pre>"); });
